{"query":"#graphql
  mutation cartCreate($country: CountryCode)
  @inContext(country: $country) {
    cartCreate {
      cart {
        id
        createdAt
        updatedAt
        checkoutUrl
        lines(first: 100) {
          edges {
            node {
              id
              quantity
              attributes {
                key
                value
              }
              merchandise {
                ... on ProductVariant {
                  id
                  title
                  product {
                    id
                    title
                    handle
                  }
                  image {
                    url
                    altText
                  }
                  price {
                    amount
                    currencyCode
                  }
                }
              }

            discountAllocations {
              discountedAmount {
                amount
                currencyCode
              }
              discountApplication {
                allocationMethod
                targetSelection
                targetType
              }
            }
            }
          }
          pageInfo {
            hasNextPage
            hasPreviousPage
          }
        }
        cost {
          totalAmount {
            amount
            currencyCode
          }
          subtotalAmount {
            amount
            currencyCode
          }
          totalTaxAmount {
            amount
            currencyCode
          }
        }
        discountAllocations {
          discountedAmount {
            amount
            currencyCode
          }
          discountApplication {
            allocationMethod
            targetSelection
            targetType
          }
        }
        discountCodes {
          code
          applicable
        }
      }
    }
  }
  ","variables":{}}
